void Solver::rephase() {
    // 1. reset the rephase counter
    rephases = 0;

    // 2. make the threshold shrink a bit more gently (avoid too aggressive shrinking)
    threshold = static_cast<int>(threshold * 0.95);

    // 3. increase the limit so that we do not rephase too often
    rephase_limit += 4096;

    // 4. choose a new phase assignment for all variables
    //    - 20 % : adopt the best phase seen so far (local_best)
    //    - 10 % : invert the best phase
    //    - 60 % : keep the current saved phase (no change)
    //    - 10 % : random polarity
    int r = rand() % 100;
    if (r < 20) {
        // adopt local best
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 30) {
        // invert local best
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else if (r < 90) {
        // keep current saved phases – nothing to do
    } else {
        // random polarity
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // 5. slightly decay VSIDS activity to diversify the search space
    var_inc *= 0.9;                     // decay the increment factor
    for (int v = 1; v <= vars; ++v) {
        activity[v] *= 0.9;             // decay activity scores
        if (vsids.inHeap(v)) vsids.update(v);
    }
}
